slationKey":"NO_212"}],"properties":{"allowDecimal":null}},"units":null,"hiNormal":null,"lowNormal":null,"hiAbsolute":null,"lowAbsolute":null},{"type":"obsControl","label":{"translationKey":"ART,_FOLLOW-UP_DATE_213","id":"213","units":"","type":"label","value":"Follow-up date"},"properties":{"mandatory":true,"notes":false,"addMore":false,"hideLabel":false,"controlEvent":true,"location":{"row":1,"column":0},"dropDown":false,"allowFutureDates":false},"id":"213","concept":{"name":"ART, Follow-up date","uuid":"88489023-783b-4021-b7a9-05ca9877bf67","datatype":"Date","conceptClass":"Misc","conceptHandler":null,"description":{"value":"Patient is to return on this date","translationKey":"ART,_FOLLOW-UP_DATE_213_DESC"},"units":null,"hiNormal":null,"lowNormal":null,"hiAbsolute":null,"lowAbsolute":null,"answers":[],"properties":{"allowDecimal":null}},"units":null,"hiNormal":null,"lowNormal":null,"hiAbsolute":null,"lowAbsolute":null,"events":{"onValueChange":"function(form) {
  var followUpDateField = form.get('ART, Follow-up date');
  if (followUpDateField && followUpDateField.getValue()) {
    var followUpDate = followUpDateField.getValue();

    // Parse the follow-up date
    var followUpDateObj = new Date(followUpDate);
    var today = new Date();

    // Reset time to midnight for accurate day calculation
    today.setHours(0, 0, 0, 0);
    followUpDateObj.setHours(0, 0, 0, 0);

    // Calculate days difference (follow-up date - today)
    var timeDiff = followUpDateObj.getTime() - today.getTime();
    var daysDispensed = Math.ceil(timeDiff / (1000 * 3600 * 24));

    // Determine supply duration based on days dispensed
    var drugSupplyPeriod = '';
    if (daysDispensed >= 10 && daysDispensed < 21) {
      drugSupplyPeriod = "2 Weeks";
    } else if (daysDispensed >= 28 && daysDispensed < 56) {
      drugSupplyPeriod = "1 month";
    } else if (daysDispensed >= 56 && daysDispensed < 84) {
      drugSupplyPeriod = "2 months";
    } else if (daysDispensed >= 84 && daysDispensed < 112) {
      drugSupplyPeriod = "3 months";
    } else if (daysDispensed >= 112 && daysDispensed < 140) {
      drugSupplyPeriod = "4 months";
    } else if (daysDispensed >= 140 && daysDispensed < 168) {
      drugSupplyPeriod = "5 months";
    } else if (daysDispensed >= 168 && daysDispensed < 196) {
      drugSupplyPeriod = "6 months";
    } else if (daysDispensed >= 196) {
      drugSupplyPeriod = "7+ months";
    }

    // Update the days dispensed field - convert to string
    var daysField = form.get('ARV drugs No. of days dispensed');
    if (daysField) {
      daysField.setValue(String(daysDispensed));
    }

    // Update the appropriate supply duration field
    var supplyField = form.get('HIVTC, ARV drugs supply duration');
    if (supplyField) {
      supplyField.setValue(drugSupplyPeriod);
    }

    var prepSupplyField = form.get('PrEP drugs supply duration');
    if (prepSupplyField) {
      prepSupplyField.setValue(drugSupplyPeriod);
    }
