  // Set bonolo health section to hidden by default
  form.get('Bonolo Health').setHidden(true);

  // Check if we're in the form builder (no patient context)
  if (!form || !form.patient || !form.patient.uuid) {
    console.log("No patient context available - form builder preview");
    return;
  }

  // Get the patient UUID from the form context
  var patientUuid = form.patient.uuid;

  // Fetch patient gender
  function fetchPatientGender() {
    var url = "/openmrs/ws/rest/v1/patient/" + patientUuid + "?v=full";
    var xhr = new XMLHttpRequest();
    xhr.open("GET", url, false);
    xhr.send();

    if (xhr.status === 200) {
      var data = JSON.parse(xhr.responseText);
      return data.person && data.person.gender ? data.person.gender : null;
    }
    return null;
  }

  var gender = fetchPatientGender();
  console.log("Patient gender:", gender);

  // If patient is male, hide female-specific fields
  if (gender === "M") {
    console.log("Patient is male - hiding female-specific fields");

    var cervicalField = form.get('HIVTC, Cervical cancer screening set');
    if (cervicalField) {
      cervicalField.setHidden(true);
      console.log("Hidden: HIVTC, Cervical cancer screening set");
    }

    var pregnancyField = form.get('HIVTC, Pregnancy, Breastfeeding');
    if (pregnancyField) {
      pregnancyField.setHidden(true);
      console.log("Hidden: HIVTC, Pregnancy, Breastfeeding");
    }
  }

  // Define all concepts we want to fetch
  var concepts = [{
      uuid: "5089AAAAAAAAAAAAAAAAAAAAAAAAAAAA",
      field: "WEIGHT",
      type: "numeric"
    },
    {
      uuid: "5090AAAAAAAAAAAAAAAAAAAAAAAAAAAA",
      field: "HEIGHT",
      type: "numeric"
    },
    {
      uuid: "90f53912-95d5-4b5c-a9eb-81f3f937225e",
      field: "IMAM, MUAC",
      type: "numeric"
    },
    {
      uuid: "c36e9c8b-3f10-11e4-adec-0800271c1b75",
      field: "Systolic",
      type: "numeric"
    },
    {
      uuid: "c379aa1d-3f10-11e4-adec-0800271c1b75",
      field: "Diastolic",
      type: "numeric"
    },
    {
      uuid: "13382e01-9f18-488b-b2d2-58ab54c82d82",
      field: "HIVTC, ART Regimen",
      type: "coded"
    }
  ];

  // Function to fetch a single concept
  function fetchConcept(concept) {
    var params = new URLSearchParams({
      patient: patientUuid,
      concept: concept.uuid,
      v: "full",
      limit: "1"
    });

    var url = "/openmrs/ws/rest/v1/obs?" + params.toString();
    var xhr = new XMLHttpRequest();
    xhr.open("GET", url, false);
    xhr.send();

    if (xhr.status === 200) {
      var data = JSON.parse(xhr.responseText);

      if (data.results && data.results.length > 0) {
        var obs = data.results[0];
        var field = form.get(concept.field);

        if (field) {
          var value = null;

          // Handle different concept types
          if (concept.type === "coded") {
            // For coded concepts, try to extract from display string
            if (obs.display) {
              var displayParts = obs.display.split(": ");
              if (displayParts.length > 1) {
                value = displayParts[1];
              }
            }
          } else {
            // For numeric concepts
            value = obs.value;
          }

          // Only set if value is not null or undefined
          if (value !== null && value !== undefined && value !== "") {
            field.setValue(String(value));
            console.log("Set", concept.field, "to", value);
          } else {
            console.log("No valid value found for", concept.field, "- leaving empty");
          }
        }
      } else {
        console.log("No data found for", concept.field);
      }
    } else {
      console.log("API call failed for", concept.field, "status:", xhr.status);
    }
  }

  // Fetch all concepts
  for (var i = 0; i < concepts.length; i++) {
    fetchConcept(concepts[i]);
  }
}","onFormSave":""},"translationsUrl":"/openmrs/ws/rest/v1/bahmniie/form/translations","referenceVersion":0,"referenceFormUuid":"81b6c6cc-65cc-478f-b3dd-885a4e393e0f"}
